using System;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;
using System.Runtime.Intrinsics.X86;
using System.Runtime.Intrinsics.Arm;

namespace ByteBitReverse;

public class BitReverser
{
    // Lookup table: reversed bits for each nibble (0x0–0xF).
    // Entry i holds the 4-bit reversal of i, already shifted to the high nibble.
    private static ReadOnlySpan<byte> NibbleReversedHigh =>
    [
        0x00, 0x80, 0x40, 0xC0, 0x20, 0xA0, 0x60, 0xE0,
        0x10, 0x90, 0x50, 0xD0, 0x30, 0xB0, 0x70, 0xF0
    ];

    // Same values shifted right 4 — reversed nibble in the low position.
    private static ReadOnlySpan<byte> NibbleReversedLow =>
    [
        0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
        0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F
    ];

    // Full 256-byte LUT for the scalar tail.
    private static readonly byte[] LookupTable = CreateLookupTable();

    private static byte[] CreateLookupTable()
    {
        var table = new byte[256];
        for (int i = 0; i < 256; i++)
        {
            table[i] = (byte)((NibbleReversedHigh[i & 0x0F]) | (NibbleReversedLow[i >> 4]));
        }
        return table;
    }

    public static void ReverseInPlace(Span<byte> data)
    {
        ref byte start = ref MemoryMarshal.GetReference(data);
        int length = data.Length;
        int offset = 0;

        if (Avx2.IsSupported && length >= 32)
        {
            var lo = Vector256.Create(NibbleReversedHigh);
            var hi = Vector256.Create(NibbleReversedLow);
            var mask = Vector256.Create((byte)0x0F);

            int lastBlockStart = length - 32;
            while (offset <= lastBlockStart)
            {
                ref byte pos = ref Unsafe.Add(ref start, offset);
                var vec = Vector256.LoadUnsafe(ref pos);

                var loNibble = vec & mask;
                var hiNibble = Vector256.ShiftRightLogical(vec.AsUInt16(), 4).AsByte() & mask;

                var result = Avx2.Shuffle(lo, loNibble) | Avx2.Shuffle(hi, hiNibble);
                result.StoreUnsafe(ref pos);
                offset += 32;
            }
        }

        if ((Ssse3.IsSupported || AdvSimd.Arm64.IsSupported) && length - offset >= 16)
        {
            var lo = Vector128.Create(NibbleReversedHigh);
            var hi = Vector128.Create(NibbleReversedLow);
            var mask = Vector128.Create((byte)0x0F);

            int lastBlockStart = length - 16;
            while (offset <= lastBlockStart)
            {
                ref byte pos = ref Unsafe.Add(ref start, offset);
                var vec = Vector128.LoadUnsafe(ref pos);

                var loNibble = vec & mask;
                var hiNibble = Vector128.ShiftRightLogical(vec.AsUInt16(), 4).AsByte() & mask;

                Vector128<byte> result;
                if (Ssse3.IsSupported)
                    result = Ssse3.Shuffle(lo, loNibble) | Ssse3.Shuffle(hi, hiNibble);
                else
                    result = AdvSimd.Arm64.VectorTableLookup(lo, loNibble) |
                             AdvSimd.Arm64.VectorTableLookup(hi, hiNibble);

                result.StoreUnsafe(ref pos);
                offset += 16;
            }
        }

        // Scalar tail using LUT
        byte[] lut = LookupTable;
        while (offset < length)
        {
            ref byte pos = ref Unsafe.Add(ref start, offset);
            pos = lut[pos];
            offset++;
        }
    }
}

